css:
 :host{display:block;max-width:100%;white-space:normal}*,*::before,*::after{box-sizing:border-box}h1,h2,p{margin:0}
.fd-glyph-art{fill:none;stroke:var(--fd-ac);stroke-width:2.8;stroke-linecap:round;stroke-linejoin:round}
[data-gallery]{cursor:pointer}[data-original-name]{object-position:50% 23%}
.prose-verdict{border-block:1px solid var(--read-edge);color:var(--read-ink);padding:8px 4px;font:14px/1.7 var(--read-serif)}.prose-verdict summary{color:var(--read-accent);cursor:pointer}.prose-verdict dl{display:grid;grid-template-columns:max-content 1fr;gap:3px 12px}.prose-verdict dd{margin:0}.prose-verdict dt{color:var(--read-muted)}
[data-reader] {
  --read-serif:"Noto Serif SC","Songti SC","SimSun",serif;
  --read-display:"STKaiti","KaiTi","Noto Serif SC",serif;
  --read-sans:"Microsoft YaHei",sans-serif;
  background:var(--read-outside);
}
[data-reader] .demo-bar[hidden]{display:none}
[data-reader] .stage{position:relative;max-width:1080px;height:100%;background:var(--read-paper);border-inline:1px solid var(--read-edge)}
.prose-toolbar{flex:none;display:flex;align-items:center;justify-content:space-between;min-height:54px;padding:8px clamp(13px,4vw,43px);gap:12px;border-bottom:1px solid var(--read-edge);background:var(--read-paper);color:var(--read-ink)}
.prose-brand,.prose-toolbar button{display:flex;align-items:center;gap:10px}
.prose-brand>span{display:grid;place-items:center;width:24px;height:25px;border:1px solid currentColor;color:var(--read-accent);font:19px/1 var(--read-display)}
.prose-brand b{font:600 18px/1.4 var(--read-serif);letter-spacing:.14em}
.prose-brand i{height:14px;border-left:1px solid var(--read-edge)}
.prose-brand small{color:var(--read-muted);font:11px var(--read-sans)}
.prose-toolbar button{min-height:34px;padding:5px 10px;border:1px solid var(--read-edge);color:var(--read-muted);font:11px var(--read-sans);gap:7px}
.prose-toolbar button:hover,.prose-toolbar button:focus-visible{border-color:var(--read-accent);color:var(--read-ink)}
.prose-toolbar button i{width:6px;height:6px;background:var(--read-accent);transform:rotate(45deg)}
.prose-toolbar button b{color:var(--read-ink)}
.prose-toolbar button span{border-left:1px solid var(--read-edge);padding-left:7px}
.prose-reader{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:var(--read-edge) var(--read-paper);font:16px/1.9 var(--read-serif);color:var(--read-ink);outline-offset:-2px}
.prose-reader:focus-visible{outline:1px solid var(--read-accent)}
.prose-volume{max-width:1000px;margin:auto;padding:24px clamp(12px,3vw,34px) 42px}
.prose-opening{position:relative;isolation:isolate;min-width:0;overflow:hidden}
.prose-opening-art{pointer-events:none}
.prose-opening-art svg,.prose-scene-art svg{display:block;width:100%;height:100%}
.prose-opening-copy,.prose-imprint{min-width:0;z-index:1}
.prose-opening h1{font:500 clamp(38px,7vw,74px)/1.1 var(--read-display);overflow-wrap:anywhere}
.prose-kicker,.prose-imprint{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;font:11px/1.65 var(--read-sans);color:var(--read-muted)}
.prose-act{font:14px/1.65 var(--read-serif);color:var(--read-muted)}
.prose-flow{max-width:688px;margin:25px auto 0;display:grid;gap:18px;min-width:0}
.prose-flow>*{min-width:0}
.prose-narration{color:var(--read-ink);line-height:2.05;overflow-wrap:anywhere}
.prose-speech{--voice:var(--read-secondary);max-width:92%;justify-self:start;min-width:0}
.prose-speech.is-player{justify-self:end;--voice:var(--read-accent)}
.prose-avatar{position:relative;display:grid;place-items:center;width:36px;height:38px;color:var(--voice);font:22px/1 var(--read-display)}
.prose-avatar img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.prose-dialogue{min-width:0;display:grid;justify-items:start}
.is-player .prose-dialogue{justify-items:end}
.prose-speaker{font:600 12px/1.5 var(--read-sans);color:var(--voice)}
.prose-bubble{font:16px/1.78 var(--read-serif);color:var(--read-ink);overflow-wrap:anywhere;min-width:0}
.prose-skill{position:relative;isolation:isolate;min-width:0;color:var(--read-ink)}
.prose-skill-copy{min-width:0}
.prose-skill-line,.prose-skill-rank{font:11px/1.55 var(--read-sans);color:var(--read-muted)}
.prose-skill h2{font:500 32px/1.22 var(--read-display);overflow-wrap:anywhere}
.prose-skill-copy p{font:14px/1.85 var(--read-serif);color:var(--read-muted)}
.prose-skill-seal{position:relative;display:grid;place-items:center;width:84px;height:84px;--fd-ac:var(--read-accent)}
.prose-skill-seal>svg:first-child{position:absolute;inset:0;width:100%;height:100%}
.prose-skill-seal .fd-glyph{width:62%;height:62%;z-index:1}
.prose-skill-seal .fd-orbit,.prose-skill-seal .fd-glyph-progress,.prose-skill-seal .fd-glyph-corners{display:none}
.prose-scene{margin-top:8px}
.prose-scene-line h2{font:500 18px/1.55 var(--read-display);overflow-wrap:anywhere}
.prose-scene-line>span,.prose-mood{font:11px var(--read-sans);color:var(--read-muted)}
.prose-scene-line{margin-bottom:12px}
[data-reader] #dp{z-index:2}
[data-reader] .panel{max-height:calc(100dvh - 132px)}
[data-reader] #dp[data-open="false"] .panel{visibility:hidden}
.large .prose-reader,.large .prose-bubble{font-size:18px}

/* 魔石碑：碑铭、切边石牒、金缮裂纹。 */
[data-reader=stone] {
  --read-paper:#181512;--read-outside:#0f0d0b;--read-edge:#4a3e31;
  --read-ink:#eee4d3;--read-muted:#bcae95;--read-accent:#ecc185;--read-secondary:#c6c09f;
}
[data-reader=stone] .prose-reader{background:radial-gradient(ellipse at 80% 0,#33241977,transparent 57%),var(--read-paper)}
[data-reader=stone] .prose-opening{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);grid-template-rows:1fr auto;min-height:290px;border-top:1px solid #735536;border-bottom:3px solid #36271d;background:linear-gradient(90deg,#211a14,#201711 56%,#110d0b),#201710}
[data-reader=stone] .prose-opening::before{content:'';position:absolute;inset:7px;border:1px solid #77543570;pointer-events:none}
[data-reader=stone] .prose-opening::after{content:'';position:absolute;inset:0;background:var(--grain);opacity:.18;z-index:-1;pointer-events:none}
[data-reader=stone] .prose-opening-copy{align-self:center;padding:32px 0 18px clamp(20px,6.1vw,70px)}
[data-reader=stone] .prose-kicker{gap:6px 12px}
[data-reader=stone] .prose-part{padding-left:8px;border-left:2px solid #cb904e;color:#e9c78e}
[data-reader=stone] .prose-opening h1{color:#ffebba;letter-spacing:.14em;margin:13px 0 12px;text-shadow:0 2px #774723,0 0 35px #c0753f52}
[data-reader=stone] .prose-act{color:#cfbfa2;letter-spacing:.10em}
[data-reader=stone] .prose-imprint{grid-column:1;grid-row:2;padding:0 0 32px clamp(20px,6.1vw,70px)}
[data-reader=stone] .prose-imprint time{padding-top:6px;border-top:1px solid #8d6843;color:#e7be84}
[data-reader=stone] .prose-opening-art{grid-column:2;grid-row:1/3;height:100%;min-height:0;position:absolute;inset:0}
[data-reader=stone] .prose-narration{text-indent:2em}
[data-reader=stone] .prose-speech{display:flex;gap:10px;align-items:start}
[data-reader=stone] .prose-speech.is-player{flex-direction:row-reverse}
[data-reader=stone] .prose-avatar{background:linear-gradient(135deg,#8d6c41,#262019);border:2px ridge #a38155;box-shadow:0 4px 10px #100b085c;clip-path:polygon(6px 0,100% 0,100% calc(100% - 6px),calc(100% - 6px) 100%,0 100%,0 6px)}
[data-reader=stone] .prose-dialogue{gap:4px}
[data-reader=stone] .prose-bubble{padding:9px 16px;background:linear-gradient(150deg,#362a20,#211c18);border-block:1px solid #68543c;box-shadow:inset 2px 0 #b59864,inset 0 -4px #13100e66;clip-path:polygon(0 0,calc(100% - 7px) 0,100% 7px,100% 100%,7px 100%,0 calc(100% - 7px))}
[data-reader=stone] .is-player .prose-bubble{box-shadow:inset -2px 0 #bf9052,inset 0 -4px #13100e66}
[data-reader=stone] .prose-skill{display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:14px;border-block:1px solid #72583a;padding:13px 15px;background:linear-gradient(110deg,#362a1d,#201a15 75%);box-shadow:inset 0 3px #19110e,inset 0 -3px #100f0d;clip-path:polygon(0 8px,9px 0,100% 0,100% calc(100% - 8px),calc(100% - 9px) 100%,0 100%)}
[data-reader=stone] .prose-skill::before{content:'';position:absolute;inset:4px 0;z-index:-1;background:var(--grain);opacity:.2}
[data-reader=stone] .prose-skill-copy{border-left:1px solid #6c543a;padding-left:14px}
[data-reader=stone] .prose-skill h2{margin:5px 0;color:#f6dbad;text-shadow:0 2px #442716}
[data-reader=stone] .prose-skill-rank{writing-mode:vertical-rl;align-self:stretch;display:grid;place-items:center;letter-spacing:.13em;padding:8px 6px;border:1px solid #9a673d;background:#301c14;color:#f2c28b}
[data-reader=stone] .prose-scene-line{display:grid;grid-template-columns:minmax(0,1fr) minmax(80px,36%);column-gap:16px;align-items:center;padding:9px 15px;background:linear-gradient(90deg,#291f17,#201813);border-top:1px solid #61472e;color:#dfba84}
[data-reader=stone] .prose-scene-art{grid-column:2;grid-row:1/4;height:29px;filter:drop-shadow(0 0 4px #e9793b90)}
[data-reader=stone] .prose-crack-halo{animation:read-ember 4.8s ease-in-out infinite alternate}
@keyframes read-ember{from{opacity:.54}to{opacity:1}}

/* 异火：火莲作中心，回旋经脉串起人物对白、斗技与换景。 */
[data-reader=fire] {
  --read-paper:#081820;--read-outside:#050f15;--read-edge:#1e454e;
  --read-ink:#e4f0ed;--read-muted:#a2c8c6;--read-accent:#82f7db;--read-secondary:#c6b4f5;
}
[data-reader=fire] .prose-toolbar{background:#0d2029}
[data-reader=fire] .prose-brand>span,[data-reader=fire] .prose-toolbar button{border-radius:99px}
[data-reader=fire] .prose-reader{background:radial-gradient(ellipse at 50% 0,#133a4080,transparent 65%),var(--read-paper)}
[data-reader=fire] .prose-opening{min-height:clamp(290px,32vw,350px);display:grid;place-items:center;text-align:center;border-block:1px solid #41867f;background:radial-gradient(ellipse at 50% 50%,#103541,#07161f 73%);margin-inline:clamp(0px,2vw,22px)}
[data-reader=fire] .prose-opening-art{position:absolute;inset:-6px -8px}
[data-reader=fire] .prose-opening-copy{max-width:min(100%,15rem);align-self:center;padding:4px 12px}
[data-reader=fire] .prose-kicker{justify-content:center;flex-direction:column;gap:2px;color:#baf4e6}
[data-reader=fire] .prose-chapter{color:#9ac6cb;font-size:10px}
[data-reader=fire] .prose-opening h1{font-size:clamp(34px,6vw,59px);color:#e4fff4;text-shadow:0 0 14px #5fffd388,0 0 36px #25bdba70;margin:5px 0 7px}
[data-reader=fire] .prose-act{color:#b3e7d6;font-size:11px;letter-spacing:.05em}
[data-reader=fire] .prose-imprint{position:absolute;inset:auto 20px 13px;justify-content:space-between;color:#a0d1cf;border-top:1px solid #4378795c;padding-top:6px}
[data-reader=fire] .prose-fire-orbit{transform-origin:0 0;animation:read-orbit 35s linear infinite}
@keyframes read-orbit{to{transform:rotate(360deg)}}
[data-reader=fire] .prose-flow{gap:17px}
[data-reader=fire] .prose-speech{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;column-gap:9px}
[data-reader=fire] .prose-speech.is-player{grid-template-columns:minmax(0,1fr) auto}
[data-reader=fire] .is-player .prose-avatar{grid-column:2;grid-row:1}
[data-reader=fire] .is-player .prose-dialogue{grid-column:1;grid-row:1}
[data-reader=fire] .prose-avatar{width:40px;height:40px;border:1px solid currentColor;border-radius:50%;background:radial-gradient(circle,#1c5260,#0c2632);box-shadow:0 0 14px color-mix(in srgb,var(--voice) 22%,transparent)}
[data-reader=fire] .prose-avatar img{border-radius:inherit}
[data-reader=fire] .prose-avatar::before{content:'';position:absolute;inset:3px;border:1px dashed currentColor;opacity:.45;border-radius:inherit;z-index:1;pointer-events:none}
[data-reader=fire] .prose-dialogue{gap:5px}
[data-reader=fire] .prose-bubble{padding:8px 17px;border-radius:0 18px 18px 13px;border:1px solid color-mix(in srgb,var(--voice) 33%,#132733);background:radial-gradient(ellipse at 0 40%,color-mix(in srgb,var(--voice) 15%,#0c1b28),#0c1b28 75%)}
[data-reader=fire] .is-player .prose-bubble{border-radius:18px 0 13px 18px;background:radial-gradient(ellipse at 100% 40%,#184248,#0c1d2b 78%)}
[data-reader=fire] .prose-skill{display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-rows:auto 1fr;column-gap:16px;margin-inline:7px;padding:12px 16px;border-inline:1px solid #5bbaa3;border-radius:31px 5px;background:radial-gradient(ellipse at 20% 60%,#194549,#0a1d29 64%);box-shadow:inset 0 1px #346269,inset 0 -1px #234951}
[data-reader=fire] .prose-skill::before{content:'';position:absolute;inset:5px;border:1px solid #51cdb133;border-radius:26px 3px;pointer-events:none}
[data-reader=fire] .prose-skill-seal{grid-row:1/3;align-self:center;filter:drop-shadow(0 0 5px #5bedd477)}
[data-reader=fire] .prose-skill-rank{grid-column:2;grid-row:1;justify-self:start;color:#a0f6dc;font-size:10px;border-radius:20px;padding:2px 9px;background:#1a4048;border:1px solid #45847e;margin-bottom:5px}
[data-reader=fire] .prose-skill-copy{grid-column:2;grid-row:2}
[data-reader=fire] .prose-skill h2{color:#e3fff9;margin:3px 0;text-shadow:0 0 13px #6df7d061}
[data-reader=fire] .prose-scene-line{display:grid;justify-items:center;gap:4px;color:#a8eee2;text-align:center}
[data-reader=fire] .prose-scene-art{width:min(100%,300px);height:46px;margin-bottom:2px}
[data-reader=fire] .prose-skill[data-arrival] .prose-skill-seal{animation:read-flare .9s ease-out both}
@keyframes read-flare{35%{filter:drop-shadow(0 0 13px #80fbdb) brightness(1.4);transform:scale(1.055)}}
/* 苍穹：上方题跋、下方山水，朱印引读。 */
[data-reader=sky] {
  --read-paper:#f7f5ed;--read-outside:#e3e9e6;--read-edge:#c6ceca;
  --read-ink:#2c4047;--read-muted:#546972;--read-accent:#3f6776;--read-secondary:#9b503a;
}
[data-reader=sky] .prose-brand>span{color:#974936;outline:1px solid #984b3438;outline-offset:2px}
[data-reader=sky] .prose-toolbar button{border:0;border-bottom:1px solid var(--read-edge)}
[data-reader=sky] .prose-reader{background:linear-gradient(#fffdf5b0,transparent 340px),var(--read-paper)}
[data-reader=sky] .prose-opening{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;border-top:2px solid #708891;border-bottom:1px solid #7a929b;background:#faf8ef}
[data-reader=sky] .prose-opening-copy{padding:21px 0 9px clamp(15px,4vw,46px)}
[data-reader=sky] .prose-kicker{color:#556c75;gap:6px 9px}
[data-reader=sky] .prose-kicker .prose-part{font-weight:600}
[data-reader=sky] .prose-chapter{border-left:1px solid #a4b2ad;padding-left:9px}
[data-reader=sky] .prose-opening h1{color:#223c4b;letter-spacing:.12em;font-size:clamp(42px,6vw,66px);margin:7px 0 5px}
[data-reader=sky] .prose-act{letter-spacing:.11em}
[data-reader=sky] .prose-imprint{justify-content:end;align-content:end;gap:5px 12px;padding:15px clamp(15px,4vw,42px) 13px;color:#536b74;text-align:right;max-width:310px}
[data-reader=sky] .prose-imprint time{color:#823e2c}
[data-reader=sky] .prose-opening-art{grid-row:2;grid-column:1/-1;height:clamp(122px,19vw,220px);width:100%}
[data-reader=sky] .prose-opening-art svg{overflow:hidden;object-fit:cover}
[data-reader=sky] .prose-flow{margin-top:28px;gap:23px}
[data-reader=sky] .prose-narration{letter-spacing:.08em}
[data-reader=sky] .prose-flow>.prose-narration:first-child::first-letter{font:650 1.32em var(--read-display);color:#9b503a}
[data-reader=sky] .prose-speech{display:flex;align-items:baseline;gap:9px}
[data-reader=sky] .prose-speech.is-player{flex-direction:row-reverse}
[data-reader=sky] .prose-avatar{flex:none;width:25px;height:25px;margin-top:4px;align-self:start;background:#f4ebe1;color:#954c36;border:2px double #9c5644;font:650 15px/1 var(--read-display);transform:rotate(-3deg)}
[data-reader=sky] .is-player .prose-avatar{transform:rotate(3deg);background:#e5edeb;color:#3e6574;border-color:#6f8f98}
[data-reader=sky] .prose-dialogue{gap:4px}
[data-reader=sky] .prose-speaker{font:600 13px/1.5 var(--read-display);align-self:end;letter-spacing:.14em}
[data-reader=sky] .prose-bubble{position:relative;padding:7px 14px 9px 24px;background:linear-gradient(90deg,#eaeae1,#faf7ee);border-top:1px solid #c8cfcb}
[data-reader=sky] .prose-bubble::before{content:'“';position:absolute;left:7px;top:3px;color:var(--voice);line-height:1.3;font-size:23px}
[data-reader=sky] .is-player .prose-bubble{padding:7px 24px 9px 14px;background:linear-gradient(-90deg,#e1eae8,#faf7ee)}
[data-reader=sky] .is-player .prose-bubble::before{content:'”';left:auto;right:7px}
[data-reader=sky] .prose-skill{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:auto auto;column-gap:12px;align-items:center;border-block:1px solid #98afb0;padding:12px 19px;background:linear-gradient(90deg,#f1f1e7,#e4ece7)}
[data-reader=sky] .prose-skill::before{content:'';position:absolute;inset:3px 0;border-block:1px solid #8da7ad3c;pointer-events:none}
[data-reader=sky] .prose-skill-seal{grid-row:1/3;grid-column:2;--fd-ac:#416d7a}
[data-reader=sky] .prose-skill-copy{grid-row:2;grid-column:1}
[data-reader=sky] .prose-skill h2{margin:4px 0;color:#2e4d5f}
[data-reader=sky] .prose-skill-rank{grid-column:1;grid-row:1;justify-self:start;color:#8a3d2a;border:1px solid #af725b;padding:1px 5px;font-family:var(--read-serif)}
[data-reader=sky] .prose-skill[data-arrival] .prose-skill-rank{animation:read-seal .6s ease-out both}
@keyframes read-seal{from{opacity:.52;transform:translateY(-5px)}}
[data-reader=sky] .prose-scene-line{display:grid;grid-template-columns:minmax(0,1fr) minmax(85px,40%);align-items:end;padding:0 0 0 12px;border-bottom:1px solid #9cafb2;border-left:3px solid #b0644b;color:#365167}
[data-reader=sky] .prose-scene-art{grid-row:1/4;grid-column:2;height:50px;max-width:220px;justify-self:end}
[data-reader=sky] .prose-scene-line h2{margin:0 0 7px}

[data-reader=stone] .dk-realm[title^="斗之气"] .dk-realm-g{white-space:nowrap;font-size:23px}
[data-reader]:not([data-motion=full]) .prose-fire-orbit,
[data-reader]:not([data-motion=full]) .prose-crack-halo,
[data-reader]:not([data-motion=full]) .prose-skill[data-arrival] *{animation:none}
@media(max-width:600px){
  .prose-toolbar{min-height:46px;padding:5px 11px}
  .prose-brand,.prose-toolbar button{gap:6px}
  .prose-brand b{font-size:15px}
  .prose-volume{padding:12px 11px 32px}
  .prose-reader,.prose-bubble{font-size:15px}
  .prose-flow{gap:15px;padding-inline:3px;margin-top:17px}
  .prose-skill h2{font-size:27px}
  .prose-skill-copy p{font-size:13px}
  .prose-skill-seal{width:61px;height:61px}
  .prose-opening-copy .prose-act{font-size:12px}
  [data-reader=stone] .prose-opening{min-height:218px;grid-template-columns:minmax(0,1.17fr) minmax(0,.83fr)}
  [data-reader=stone] .prose-opening-copy{padding:17px 0 13px 17px}
  [data-reader=stone] .prose-imprint{padding:0 0 17px 17px;gap:3px 8px}
  [data-reader=stone] .prose-opening-art{inset:8px -41% -5px -21%}
  [data-reader=stone] .prose-skill{gap:7px;padding:10px 9px}
  [data-reader=stone] .prose-skill-copy{padding-left:8px}
  [data-reader=stone] .prose-skill-rank{padding:4px 3px;font-size:10px}
  [data-reader=fire] .prose-opening{min-height:273px;margin:0}
  [data-reader=fire] .prose-opening-art{inset:-5px -40%;height:100%}
  [data-reader=fire] .prose-imprint{inset:auto 12px 6px}
  [data-reader=fire] .prose-opening h1{font-size:41px}
  [data-reader=fire] .prose-opening-copy{max-width:200px}
